mapper.select:
SELECT t.id, t.`name`, t.note, t.business_id, t.root, t.simple_name, t.`state`, t.create_time, t.tenant_rank,t.score, t.create_user_cn_name, if(tu.id is null, 0, 1) as be_have_super, t.balance,t.tax_no, t.address, t.phone FROM sys_tenant t LEFT JOIN sys_tenant_user tu on t.id = tu.tenant_id and LOWER(tu.user_no) = LOWER(CONCAT(t.root,'_super'))
AND t.name LIKE CONCAT('%',#{name,jdbcType=CHAR},'%')
AND t.state = #{state,jdbcType=CHAR}
order by t.create_time desc LIMIT #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}

select count(1) FROM sys_tenant t LEFT JOIN sys_tenant_user tu on t.id = tu.tenant_id and LOWER(tu.user_no) = LOWER(CONCAT(t.root,'_super'))
AND t.name LIKE CONCAT('%',#{name,jdbcType=CHAR},'%')
AND t.state = #{state,jdbcType=CHAR}
